python3 -c "
import json
with open('/app/resources/treasury_bulletin_1963_12.json', 'r') as f:
    data = json.load(f)

# Try to find exchange rate data
def find_exchange_rates(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            if 'exchange' in k.lower() or 'pound' in k.lower() or 'sterling' in k.lower() or 'gbp' in k.lower() or 'usd' in k.lower():
                print(f'{new_path}: {v}')
            find_exchange_rates(v, new_path)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_exchange_rates(item, f'{path}[{i}]')

find_exchange_rates(data)
